import random
import re
from functools import lru_cache
from itertools import combinations, permutations


def _parse(inp: str) -> tuple[int, list[tuple[int, int]]] | None:
    tokens = inp.split()
    if len(tokens) < 2 or len(tokens) > 400002:
        return None

    integer = re.compile(r"([+-]?)0*([0-9]{1,6})")
    values = []
    for token in tokens:
        match = integer.fullmatch(token)
        if match is None:
            return None
        sign, digits = match.groups()
        values.append(int(sign + digits))

    size, count = values[:2]
    if not (1 <= size <= 200000 and 0 <= count <= 200000):
        return None
    if len(values) != 2 + 2 * count:
        return None

    edges = []
    seen = set()
    for index in range(2, len(values), 2):
        u, v = values[index], values[index + 1]
        if not (1 <= u < v <= size) or (u, v) in seen:
            return None
        edges.append((u, v))
        seen.add((u, v))
    return size, edges


def _coloring(
    size: int, edges: list[tuple[int, int]]
) -> tuple[int, int] | None:
    neighbors = [[] for _ in range(size + 1)]
    for u, v in edges:
        neighbors[u].append(v)
        neighbors[v].append(u)

    colors = [-1] * (size + 1)
    components = 0
    for vertex in range(1, size + 1):
        if colors[vertex] != -1:
            continue
        components += 1
        colors[vertex] = 0
        pending = [vertex]
        while pending:
            u = pending.pop()
            for v in neighbors[u]:
                if colors[v] == -1:
                    colors[v] = 1 - colors[u]
                    pending.append(v)
                elif colors[v] == colors[u]:
                    return None
    return components, colors.count(1)


def _format(size: int, edges: list[tuple[int, int]]) -> str:
    lines = [f"{size} {len(edges)}"]
    lines.extend(f"{u} {v}" for u, v in edges)
    return "\n".join(lines) + "\n"


def validate_input(inp: str) -> bool:
    graph = _parse(inp)
    return graph is not None and _coloring(*graph) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = [
        "1 0\n",
        "2 0\n",
        "2 1\n1 2\n",
        "3 2\n1 2\n2 3\n",
        "4 3\n1 2\n2 3\n3 4\n",
        "4 2\n1 2\n3 4\n",
        "5 4\n1 2\n2 3\n3 4\n1 4\n",
        "6 0\n",
        "6 5\n1 2\n1 3\n1 4\n1 5\n1 6\n",
        "6 9\n1 4\n1 5\n1 6\n2 4\n2 5\n2 6\n3 4\n3 5\n3 6\n",
    ][:max(0, n)]
    while len(cases) < n:
        size = rng.randint(1, 6)
        colors = [rng.randrange(2) for _ in range(size + 1)]
        density = rng.choice((0.2, 0.5, 0.8, 1.0))
        edges = [
            (u, v)
            for u, v in combinations(range(1, size + 1), 2)
            if colors[u] != colors[v] and rng.random() < density
        ]
        rng.shuffle(edges)
        cases.append(_format(size, edges))
    return cases


def gen_stress(seed: int) -> list[str]:
    size = 200000
    path_with_chord = [(u, u + 1) for u in range(1, size)]
    path_with_chord.append((1, 4))

    matching = [(u, u + 1) for u in range(1, 160000, 2)]
    rng = random.Random(seed)
    rng.shuffle(matching)
    return [_format(size, path_with_chord), _format(size, matching)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    tokens = out.split()
    if tokens not in (["Aoki"], ["Takahashi"]):
        return [("POST-4", "Expected exactly one token, Aoki or Takahashi.")]

    graph = _parse(inp)
    if graph is None:
        return []
    size, edges = graph
    coloring = _coloring(size, edges)
    if coloring is None:
        return []

    components, side_size = coloring
    if components == 1:
        vacancies = side_size * (size - side_size) - len(edges)
        if vacancies == 0 and tokens[0] != "Takahashi":
            return [("POST-3", "Aoki has no legal move in the initial graph.")]
        if vacancies == 1 and tokens[0] != "Aoki":
            return [("POST-3", "The sole legal move leaves no reply.")]
    elif size == 2 and tokens[0] != "Aoki":
        return [("POST-3", "Adding the only possible edge leaves no reply.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index in range(n):
        size = rng.randint(4, 6)
        active = list(range(1, size))
        rng.shuffle(active)
        split = rng.randint(1, len(active) - 1)
        possible = [
            (min(u, v), max(u, v))
            for u in active[:split]
            for v in active[split:]
        ]
        edges = rng.sample(possible, rng.randint(2, len(possible)))
        if index % 2 == 0:
            labels = list(range(size + 1))
            incident = edges[0][0]
            labels[incident], labels[size] = labels[size], labels[incident]
            transformed = [
                (min(labels[u], labels[v]), max(labels[u], labels[v]))
                for u, v in edges
            ]
        else:
            transformed = edges[::-1]
        pairs.append(
            ("POST-5", "equal", _format(size, edges), _format(size, transformed))
        )
    return pairs


def reference_small(inp: str) -> str | None:
    graph = _parse(inp)
    if graph is None:
        return None
    size, edges = graph
    if size > 6:
        return None

    vertices = range(1, size + 1)
    edge_bits = {
        edge: 1 << index
        for index, edge in enumerate(combinations(vertices, 2))
    }

    # Every odd closed walk contains a simple odd cycle.
    odd_cycles = []
    for length in range(3, size + 1, 2):
        for subset in combinations(vertices, length):
            first = subset[0]
            for rest in permutations(subset[1:]):
                if rest[0] > rest[-1]:
                    continue
                walk = (first,) + rest + (first,)
                cycle = 0
                for u, v in zip(walk, walk[1:]):
                    cycle |= edge_bits[min(u, v), max(u, v)]
                odd_cycles.append(cycle)

    initial = sum(edge_bits[edge] for edge in edges)
    if any((initial & cycle) == cycle for cycle in odd_cycles):
        return None

    @lru_cache(maxsize=None)
    def wins(state: int) -> bool:
        for bit in edge_bits.values():
            if state & bit:
                continue
            child = state | bit
            if any((child & cycle) == cycle for cycle in odd_cycles):
                continue
            if not wins(child):
                return True
        return False

    return "Aoki\n" if wins(initial) else "Takahashi\n"
